// Ensures all associated dynamically allocated buffers are properly released to
// prevent leaks.
TEST(Int64ArrayTest, DestroyOnPopulatedArrayFreesMemory) {
    GamesmanAllocatorOptions options;
    GamesmanAllocatorOptionsSetDefaults(&options);

    // Constraining the pool size allows us to reliably track memory allocations
    // and deallocations.
    options.pool_size = 256;
    GamesmanAllocator *allocator = GamesmanAllocatorCreate(&options);
    ASSERT_NE(allocator, nullptr);

    const size_t initial_pool_size =
        GamesmanAllocatorGetRemainingPoolSize(allocator);

    Int64Array array;
    Int64ArrayInitAllocator(&array, allocator);

    ASSERT_TRUE(Int64ArrayPushBack(&array, 42))
        << "Initial push back must succeed to test memory deallocation.";

    const size_t pool_size_after_push =
        GamesmanAllocatorGetRemainingPoolSize(allocator);
    EXPECT_LT(pool_size_after_push, initial_pool_size)
        << "Pushing an element must consume allocator memory pool space.";

    Int64ArrayDestroy(&array);

    const size_t final_pool_size =
        GamesmanAllocatorGetRemainingPoolSize(allocator);
    EXPECT_EQ(final_pool_size, initial_pool_size)
        << "Destroying the populated array must return all associated memory "
           "back to the allocator pool.";

    GamesmanAllocatorRelease(allocator);
}

