// Validates deep-copy semantics so modifications to the new array do not affect
// the original.
TEST(Int64ArrayTest, CopyFromPopulatedArrayDuplicatesData) {
    Int64Array src;
    Int64ArrayInit(&src);
    ASSERT_TRUE(Int64ArrayPushBack(&src, 10));
    ASSERT_TRUE(Int64ArrayPushBack(&src, 20));

    Int64Array dest;
    ASSERT_TRUE(Int64ArrayInitCopy(&dest, &src));
    EXPECT_EQ(dest.size, 2);
    EXPECT_GE(dest.capacity, 2);
    ASSERT_NE(dest.array, nullptr);
    EXPECT_NE(dest.array, src.array) << "Deep copy must allocate a new "
                                        "internal array, not copy the pointer.";
    EXPECT_EQ(dest.array[0], 10);
    EXPECT_EQ(dest.array[1], 20);

    // Modify destination to ensure the source is completely unaffected
    dest.array[0] = 99;
    EXPECT_EQ(src.array[0], 10) << "Modifying the copied array should not "
                                   "affect the original source array.";

    Int64ArrayDestroy(&dest);
    Int64ArrayDestroy(&src);
}

