// Verifies graceful failure handling when the memory pool is exhausted during a
// clone operation.
TEST(Int64ArrayTest, CopyReturnsFalseWhenAllocationFails) {
    GamesmanAllocatorOptions options;
    GamesmanAllocatorOptionsSetDefaults(&options);
    options.pool_size =
        256;  // Constrain the pool to a small size for quick exhaustion
    GamesmanAllocator *allocator = GamesmanAllocatorCreate(&options);
    ASSERT_NE(allocator, nullptr);

    Int64Array src;
    Int64ArrayInitAllocator(&src, allocator);

    // Populate source array to ensure the copy operation requires an allocation
    Int64ArrayPushBack(&src, 1);
    Int64ArrayPushBack(&src, 2);
    Int64ArrayPushBack(&src, 3);
    Int64ArrayPushBack(&src, 4);

    // Exhaust the memory pool reliably by requesting small allocations until it
    // fails. This avoids issues with padding and alignment unpredictability.
    std::vector<void *> exhausting_ptrs;
    while (true) {
        void *ptr = GamesmanAllocatorAllocate(allocator, 1);
        if (ptr == nullptr) {
            break;
        }
        exhausting_ptrs.push_back(ptr);
    }

    Int64Array dest;
    // Initialize destination with arbitrary values to verify it remains
    // untouched on failure
    dest.allocator = nullptr;
    dest.array = nullptr;
    dest.size = 0;
    dest.capacity = 0;

    EXPECT_FALSE(Int64ArrayInitCopy(&dest, &src))
        << "InitCopy must return false when the allocator is completely "
           "exhausted.";

    EXPECT_EQ(dest.array, nullptr) << "The destination internal array pointer "
                                      "must remain null on allocation failure.";
    EXPECT_EQ(dest.size, 0);
    EXPECT_EQ(dest.capacity, 0);

    // Clean up the exhausted memory first to ensure successful deallocation of
    // src
    for (void *ptr : exhausting_ptrs) {
        GamesmanAllocatorDeallocate(allocator, ptr);
    }

    Int64ArrayDestroy(&dest);
    Int64ArrayDestroy(&src);
    GamesmanAllocatorRelease(allocator);
}

