// Ensures amortized O(1) performance by verifying capacity expands correctly
// when limits are reached.
TEST(Int64ArrayTest, PushBackFullArrayTriggersExpansion) {
    Int64Array array;
    Int64ArrayInit(&array);

    ASSERT_TRUE(Int64ArrayPushBack(&array, 1));
    const int64_t initial_capacity = array.capacity;

    // Push elements until the array is forced to expand its capacity.
    bool capacity_expanded = false;
    for (int64_t i = 2; i <= initial_capacity + 2; ++i) {
        ASSERT_TRUE(Int64ArrayPushBack(&array, i));
        if (array.capacity > initial_capacity) {
            capacity_expanded = true;
            break;
        }
    }

    EXPECT_TRUE(capacity_expanded)
        << "Array capacity must increase after exceeding its initial limit.";

    Int64ArrayDestroy(&array);
}

