// Ensures the array remains in a valid, unmodified state if a reallocation
// fails.
TEST(Int64ArrayTest, PushBackFailsSafelyOnMemoryExhaustion) {
    GamesmanAllocatorOptions options;
    GamesmanAllocatorOptionsSetDefaults(&options);
    options.pool_size = 256;  // Small pool size to force exhaustion quickly
    GamesmanAllocator *allocator = GamesmanAllocatorCreate(&options);
    ASSERT_NE(allocator, nullptr);

    Int64Array array;
    Int64ArrayInitAllocator(&array, allocator);

    int64_t last_successful_size = 0;
    int64_t last_successful_capacity = 0;
    bool failure_encountered = false;

    // Keep pushing until an allocation inevitably fails.
    for (int64_t i = 0; i < 1000; ++i) {
        if (!Int64ArrayPushBack(&array, i)) {
            failure_encountered = true;
            break;
        }
        last_successful_size = array.size;
        last_successful_capacity = array.capacity;
    }

    ASSERT_TRUE(failure_encountered) << "Expected the memory pool to run out, "
                                        "triggering a PushBack failure.";

    EXPECT_EQ(array.size, last_successful_size)
        << "The logical size must not increment if the insertion failed.";
    EXPECT_EQ(array.capacity, last_successful_capacity)
        << "The internal capacity must remain unchanged after a failed "
           "expansion.";
    ASSERT_NE(array.array, nullptr)
        << "The previously allocated buffer must remain intact on failure.";

    Int64ArrayDestroy(&array);
    GamesmanAllocatorRelease(allocator);
}

