namespace {

// Helper comparator for ascending order
int CompareAscending(const void *a, const void *b) {
    const int64_t val1 = *static_cast<const int64_t *>(a);
    const int64_t val2 = *static_cast<const int64_t *>(b);
    if (val1 < val2) return -1;
    if (val1 > val2) return 1;
    return 0;
}

// Helper comparator for descending order
int CompareDescending(const void *a, const void *b) {
    const int64_t val1 = *static_cast<const int64_t *>(a);
    const int64_t val2 = *static_cast<const int64_t *>(b);
    if (val1 < val2) return 1;
    if (val1 > val2) return -1;
    return 0;
}

}  // namespace

// Validates standard sequential ordering using a standard integer comparison.
TEST(Int64ArrayTest, SortExplicitOrdersAscending) {
    Int64Array array;
    Int64ArrayInit(&array);

    Int64ArrayPushBack(&array, 42);
    Int64ArrayPushBack(&array, 7);
    Int64ArrayPushBack(&array, 100);
    Int64ArrayPushBack(&array, -5);

    Int64ArraySortExplicit(&array, CompareAscending);

    EXPECT_EQ(array.size, 4);
    EXPECT_EQ(array.array[0], -5)
        << "Smallest element must be at the first index.";
    EXPECT_EQ(array.array[1], 7);
    EXPECT_EQ(array.array[2], 42);
    EXPECT_EQ(array.array[3], 100)
        << "Largest element must be at the last index.";

    Int64ArrayDestroy(&array);
}

