// Ensures the array preserves its original state if an expansion request cannot
// be fulfilled.
TEST(Int64ArrayTest, ResizeFailsSafelyOnMemoryExhaustion) {
    GamesmanAllocatorOptions options;
    GamesmanAllocatorOptionsSetDefaults(&options);
    options.pool_size = 256;  // Small pool size for fast exhaustion
    GamesmanAllocator *allocator = GamesmanAllocatorCreate(&options);
    ASSERT_NE(allocator, nullptr);

    Int64Array array;
    Int64ArrayInitAllocator(&array, allocator);

    Int64ArrayPushBack(&array, 7);
    Int64ArrayPushBack(&array, 11);

    const int64_t original_size = array.size;
    const int64_t original_capacity = array.capacity;
    const int64_t *original_ptr = array.array;

    // Exhaust the memory pool reliably
    std::vector<void *> exhausting_ptrs;
    while (true) {
        void *ptr = GamesmanAllocatorAllocate(allocator, 1);
        if (ptr == nullptr) {
            break;
        }
        exhausting_ptrs.push_back(ptr);
    }

    // Attempt to resize to a massive size that demands reallocation
    EXPECT_FALSE(Int64ArrayResize(&array, 5000))
        << "Resize must return false when the memory pool is exhausted.";

    EXPECT_EQ(array.size, original_size)
        << "Logical size must remain unaltered on failed resize.";
    EXPECT_EQ(array.capacity, original_capacity)
        << "Internal capacity must remain unaltered on failed resize.";
    EXPECT_EQ(array.array, original_ptr)
        << "Internal pointer must not be corrupted or freed on failed resize.";
    EXPECT_EQ(array.array[0], 7);
    EXPECT_EQ(array.array[1], 11);

    // Clean up exhausted memory
    for (void *ptr : exhausting_ptrs) {
        GamesmanAllocatorDeallocate(allocator, ptr);
    }

    Int64ArrayDestroy(&array);
    GamesmanAllocatorRelease(allocator);
}

